cd /repo/.otter/worktrees/wt && python3 - <<'PYEOF'
src = open('src/frameworks/agent/bash-safety-guard.ts').read()

# 1) pkillTargetsOtter 剥注释（shell # 起为注释，非目标语义；词元前于注释命中不受影响）
old = """function pkillTargetsOtter(segment: string): boolean {
  const lower = segment.toLowerCase();
  return OTTER_PROCESS_PATTERNS.some(
    pat => new RegExp("\\\\b" + pat.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&") + "\\\\b").test(lower),
  );
}"""
new = """function pkillTargetsOtter(segment: string): boolean {
  // #852 r1（S3-F1）：剥 shell 注释再判定——`pkill -f myapp # node` 的 `# node` 是注释
  // 不是目标，不剥会让注释文本命中进程名表（node 在表内）造成误拦。
  const noComment = segment.replace(/#.*$/, "");
  const lower = noComment.toLowerCase();
  return OTTER_PROCESS_PATTERNS.some(
    pat => new RegExp("\\\\b" + pat.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&") + "\\\\b").test(lower),
  );
}"""
assert old in src, "pkill block not found"
src = src.replace(old, new, 1)

# 2) hasIndirectPidTarget 剥 xargs 形（xargs kill 已在段查表层被识别，间接层重复命中同文本是冗余）
old2 = """/** 检查 kill 段是否有非字面量 PID 目标。
 * 非字面量 = 变量引用 / 命令替换 / 管道 / eval / hex 转义
 */
function hasIndirectPidTarget(segment: string): boolean {
  return INDIRECT_PID_PATTERNS.some(pat => pat.test(segment));
}"""
new2 = """/** 检查 kill 段是否有非字面量 PID 目标。
 * 非字面量 = 变量引用 / 命令替换 / 管道 / eval / hex 转义
 * #852 r1（S3-F3）：段文本先剥「xargs … kill」形态再测——该形态由段查表层的
 * 前缀词剥除负责识别（xargs 语义=读 stdin 喂 PID，无 stdin 时 kill 无目标），
 * 间接层的 /xargs\\\\b[^|;&]*\\\\bkill\\\\b/ 模式会冗余命中同文本（剥除后字面 PID 段正常走
 * 字面量判定，与裸 kill 字面量语义一致）。
 */
function hasIndirectPidTarget(segment: string): boolean {
  const stripped = segment.replace(/xargs\\b[^|;&]*\\bkill\\b/i, "");
  return INDIRECT_PID_PATTERNS.some(pat => pat.test(stripped));
}"""
assert old2 in src, "indirect block not found"
src = src.replace(old2, new2, 1)
open('src/frameworks/agent/bash-safety-guard.ts','w').write(src)
print("done")
