  it("交接模式下 waiter 从交接开始重新计时——交接自取锁不死等自己（9/23 四獭连续超时根因）", async () => {
    // Why: 锁释放直接移交队首 waiter 且 heldAt 重置；交接换世需二次取同一把锁排在自己后面，
    //  不重置纪元则队首 waiter 看到的持有时长从 0 重新长，等满 120s 时交接仍持锁 → 必死。
    //  本测试用缩短的 waiter 超时模拟：开启交接（重置 heldAt）后二次取锁应能随 release 正常交接。
    const lock = new SimpleLockManager(60); // 默认 waiter 60ms（模拟非交接 30s）
    const release1 = await lock.acquire("session:otter-a");
    // 模拟旧 turn 已持有 50ms（接近 60ms 超时）
    await new Promise(r => setTimeout(r, 50));
    // 交接开始：重置纪元 + waiter 超时延长到 120s（此处 handoff 模式下为 120000ms，测试用默认参数即可）
    lock.setHandoffMode("session:otter-a", true);
    // 交接换世二次取锁：排在 release1 后面
    const secondAcquire = lock.acquire("session:otter-a");
    // 交接做完释放 → 队首 waiter（第二次取锁）应正常拿到，不超时
    await new Promise(r => setTimeout(r, 20));
    release1();
    const release2 = await secondAcquire;
    release2();
    lock.setHandoffMode("session:otter-a", false);
  });

  it("未开启交接模式时，旧持有接近超时的 waiter 仍按原预算超时（行为不变式）", async () => {
    const lock = new SimpleLockManager(60);
    const release1 = await lock.acquire("session:otter-b");
    await new Promise(r => setTimeout(r, 50));
    await expect(lock.acquire("session:otter-b")).rejects.toThrow("Lock acquire timeout");
    release1();
  });
});
