/** DM 消息信封解析（后端侧）：仅当 content 是「含字符串 content + 数组 attachments」的 JSON 才认信封，
 *  其余一律按纯文本（用户手粘类 JSON 文本不被误判——F20260923dmimg 严重 3 处置）。 */
function parseDmEnvelope(content: string): { content: string; attachments: DmAttachmentRef[] } | null {
  if (!content || content[0] !== '{') return null;
  try {
    const parsed = JSON.parse(content) as Record<string, unknown>;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
    if (typeof parsed.content !== 'string' || !Array.isArray(parsed.attachments)) return null;
    const attachments = (parsed.attachments as unknown[]).filter(
      (item): item is DmAttachmentRef =>
        !!item && typeof item === 'object' &&
        typeof (item as DmAttachmentRef).id === 'string' &&
        typeof (item as DmAttachmentRef).name === 'string',
    );
    if (attachments.length === 0) return null;
    return { content: parsed.content, attachments };
  } catch {
    return null;
  }
}
